import json
P = {}
def add(lote, cat, slug, titulo, foco):
    P.setdefault(lote, []).append({"category": cat, "slug": slug, "titulo_sugerido": titulo, "foco": foco})

o='oracoes-do-dia-a-dia'; d='duvidas-da-fe'; c='catecismo'; s='sacramentos'; doc='documentos-da-igreja'
# A: orações por necessidade
add('A',o,'oracao-para-ansiedade-e-paz-interior','Oração para a ansiedade: paz interior pela fé','Ansiedade à luz da fé (Fl 4,6-7; Mt 6,25-34; 1Pd 5,7). Orações tradicionais adequadas (Lembrai-vos/Memorare, Salmo 23, Jesus eu confio em vós). Deixar claro que oração não substitui tratamento médico/psicológico quando necessário.')
add('A',o,'oracao-para-conseguir-emprego','Oração para conseguir emprego: fé e confiança','Dignidade do trabalho (CIC 2427-2428), São José Operário (1º de maio), devoção a São Caetano no Brasil (7 de agosto) com cuidado. Oração a São José tradicional.')
add('A',o,'oracao-antes-de-viajar','Oração antes de viajar: proteção no caminho','Itinerário (oração tradicional da Igreja para viagem, citar como existente no Breviário sem reproduzir texto longo se não tiver certeza), São Rafael Arcanjo (livro de Tobias), São Cristóvão. Salmo 121.')
add('A',o,'oracao-antes-da-prova-e-dos-estudos','Oração antes da prova e dos estudos','Oração de São Tomás de Aquino antes do estudo (Ante studium) só se tiver o texto tradicional; Espírito Santo (Vinde Espírito Santo); dom da sabedoria e ciência (CIC 1831); estudar com responsabilidade.')
add('A',o,'bencao-da-casa-nova','Bênção da casa nova: como pedir e rezar','Bênção de casas pelo sacerdote (Ritual de Bênçãos), como pedir na paróquia, oração em família na nova casa, água benta, entronização do Sagrado Coração (devoção).')
add('A',o,'oracao-pelos-filhos','Oração pelos filhos: como rezar por eles','Missão dos pais (CIC 2221-2226), Santa Mônica como modelo, bênção dos pais aos filhos, Anjo da Guarda.')
add('A',o,'oracao-pelo-casamento','Oração pelo casamento e pelo cônjuge','Matrimônio como sacramento (CIC 1601, 1641-1642), rezar juntos, Sagrada Família, Tobias e Sara (Tb 8,4-8) como oração bíblica dos esposos.')
add('A',o,'oracao-da-noite-antes-de-dormir','Oração da noite: como rezar antes de dormir','Exame de consciência breve, Ato de contrição, Completas (link /liturgia-das-horas/completas-oracao-antes-de-dormir), Salmo 4 e Salmo 91 (90), Anjo da Guarda.')
add('A',o,'oracao-da-manha-oferecimento-do-dia','Oração da manhã: o oferecimento do dia','Oferecimento do dia (tradição do Apostolado da Oração), Laudes, sinal da cruz ao acordar, Anjo da Guarda.')
add('A',o,'oracao-de-gratidao-a-deus','Oração de gratidão: como agradecer a Deus','Ação de graças na Bíblia (1Ts 5,18; Sl 136; Lc 17,11-19 os dez leprosos), Eucaristia significa ação de graças (CIC 1360), Te Deum como hino tradicional de ação de graças.')
# B: luto e sacramentais
add('B',d,'o-que-a-igreja-ensina-sobre-a-morte','O que a Igreja ensina sobre a morte?','CIC 1005-1014, morte como fim da peregrinação, juízo particular (CIC 1021-1022), ressurreição da carne, esperança cristã.')
add('B',d,'missa-de-setimo-dia-o-que-e','Missa de sétimo dia: o que é e por que rezar','Costume de oferecer Missa pelos falecidos, intenção de Missa, sufrágio (CIC 1032, 1371), sétimo e trigésimo dia são costumes, não obrigação; como pedir na paróquia.')
add('B',o,'oracao-pelos-falecidos','Oração pelos falecidos: como rezar pelos mortos','"Dai-lhes, Senhor, o descanso eterno" (Requiem aeternam), 2Mc 12,46, purgatório (CIC 1030-1032), Terço pelas almas.')
add('B',d,'a-igreja-permite-a-cremacao','A Igreja permite a cremação? O que diz a doutrina','Instrução Ad resurgendum cum Christo (2016, Congregação para a Doutrina da Fé): permitida, preferência pelo sepultamento, cinzas em lugar sagrado, não espalhar nem guardar em casa. CDC cân. 1176 §3.')
add('B',d,'como-viver-o-luto-cristao','Como viver o luto à luz da fé cristã','Jesus chorou por Lázaro (Jo 11,35), esperança (1Ts 4,13), sufrágios, comunhão dos santos, procurar ajuda da comunidade e, se preciso, de profissionais.')
add('B',d,'exequias-o-funeral-catolico','Exéquias: como é o funeral católico','Ritual de Exéquias, celebração da Palavra ou Missa de corpo presente, encomendação, quem pode presidir (leigos podem dirigir celebração em alguns casos), CIC 1684-1690.')
add('B',d,'indulgencia-pelos-falecidos-em-finados','Indulgência pelos falecidos em Finados: como obter','Indulgência plenária aplicável às almas: visita ao cemitério de 1 a 8 de novembro e visita a igreja em 2 de novembro com Pai-Nosso e Credo, condições habituais (confissão, comunhão, oração pelo Papa, desapego). Manual das Indulgências. CIC 1471-1479.')
add('B',d,'o-que-sao-sacramentais','O que são sacramentais? Diferença dos sacramentos','CIC 1667-1679, bênçãos, objetos, diferença em relação aos sacramentos, religiosidade popular.')
add('B',d,'crucifixo-significado-e-uso','Crucifixo: significado e por que os católicos usam','Diferença entre cruz e crucifixo, 1Cor 1,23 e Gl 6,14, Sexta-feira Santa adoração da Cruz, crucifixo na casa e no altar.')
add('B',d,'medalhas-catolicas-significado','Medalhas católicas: significado e uso correto','Sacramentais, não amuletos (CIC 2111 superstição), Medalha Milagrosa (link /devocoes-marianas/a-medalha-milagrosa-historia-e-promessas), medalha de São Bento (link /santos-e-oracoes/sao-bento-de-nursia-pai-do-monaquismo-ocidental), benzer a medalha.')
add('B',d,'o-terco-precisa-ser-bento','O terço precisa ser bento? Como benzer objetos','Bênção de objetos por sacerdote ou diácono, valor do objeto bento, terço não bento também pode ser rezado, onde pedir a bênção.')
add('B',d,'quem-pode-benzer-objetos-e-pessoas','Quem pode dar bênçãos na Igreja Católica?','CIC 1669 (todo batizado é chamado a ser bênção; quanto mais uma bênção diz respeito à vida eclesial, mais é reservada ao ministro ordenado), bênção dos pais aos filhos, bênçãos reservadas.')
add('B',d,'imposicao-das-cinzas-significado','Imposição das cinzas: significado na Quarta-feira','Gn 3,19, "Convertei-vos e crede no Evangelho" (Mc 1,15), quem pode receber (inclusive não católicos), jejum e abstinência na Quarta-feira de Cinzas (CDC cân. 1251).')
# C: Missa e família
add('C',d,'gestos-na-missa-significado','Gestos na Missa: sinal da cruz, genuflexão e mais','Sinal da cruz, genuflexão, inclinação, ajoelhar, ficar de pé, bater no peito, sinal da paz. Instrução Geral do Missal Romano (IGMR 42-44, 274-275) apenas se tiver certeza dos números; caso contrário cite IGMR sem número.')
add('C',d,'vestes-liturgicas-significado','Vestes litúrgicas: alva, estola, casula e mais','Alva, cíngulo, amito, estola (como o diácono usa), casula, dalmática, pluvial, cores litúrgicas (link /duvidas-da-fe/o-que-representam-as-cores-liturgicas-da-missa se existir na lista).')
add('C',d,'objetos-liturgicos-da-missa','Objetos da Missa: cálice, patena, âmbula e mais','Cálice, patena, âmbula (cibório), corporal, sanguíneo (purificador), pala, galhetas, lavabo, missal, lecionário, turíbulo, sacrário.')
add('C',d,'ato-penitencial-da-missa','Ato penitencial da Missa: o que significa','Confesso a Deus todo-poderoso (texto do Missal), Senhor tende piedade (Kyrie), perdoa pecados veniais, não substitui a confissão sacramental de pecados graves.')
add('C',d,'liturgia-da-palavra-na-missa','Liturgia da Palavra: leituras, salmo e homilia','Primeira leitura, salmo responsorial, segunda leitura aos domingos, aclamação, Evangelho, homilia, Credo, oração dos fiéis; ciclo A/B/C e anos pares/ímpares; link /liturgia-diaria.')
add('C',d,'oracao-eucaristica-centro-da-missa','Oração Eucarística: o coração da Missa','Prefácio, Santo, epiclese, narrativa da instituição e consagração, anamnese, intercessões, doxologia e Amém; CIC 1352-1354.')
add('C',d,'como-comungar-corretamente','Como comungar: na mão, na boca e as disposições','Disposições (estado de graça, jejum de uma hora CDC cân. 919), modos de receber permitidos, dizer Amém, ação de graças; links existentes sobre jejum e pecado mortal.')
add('C',d,'o-gloria-e-o-credo-na-missa','Glória e Credo na Missa: quando se rezam?','Glória aos domingos fora do Advento e Quaresma, solenidades e festas; Credo aos domingos e solenidades; Credo niceno-constantinopolitano ou apostólico.')
add('C',o,'como-rezar-com-criancas','Como rezar com crianças: guia para pais','Idades, orações simples, sinal da cruz, rezar antes de dormir e das refeições, exemplo dos pais, CIC 2226.')
add('C',c,'igreja-domestica-familia-crista','Igreja doméstica: a família cristã segundo a Igreja','CIC 1655-1658, 2204-2206, Familiaris consortio (São João Paulo II, 1981), Amoris laetitia (Francisco, 2016) com cuidado.')
add('C',s,'como-preparar-os-filhos-para-a-primeira-comunhao','Como preparar os filhos para a Primeira Comunhão','Papel dos pais junto com a catequese paroquial, idade da razão (CDC cân. 914), primeira confissão antes, roupa, presente, festa sóbria; link /sacramentos/a-primeira-comunhao-preparacao-e-significado.')
add('C',s,'papel-dos-pais-no-batismo','O papel dos pais no Batismo dos filhos','Batizar nas primeiras semanas (CDC cân. 867), compromisso de educar na fé, diferença do papel dos padrinhos (link existente sobre padrinhos), escolha do nome (CDC cân. 855).')
add('C',c,'como-transmitir-a-fe-aos-adolescentes','Como transmitir a fé aos adolescentes','Diálogo, testemunho, grupos de jovens, Crisma, liberdade e paciência; tom pastoral, sem promessas fáceis.')
add('C',o,'oracao-em-familia-como-comecar','Oração em família: como começar e manter','Momentos (refeições, noite, domingo), Terço em família (link existente), leitura do Evangelho, bênção dos filhos.')
# D1: namoro e vocação + virtudes teologais
add('D1',d,'namoro-catolico-como-viver','Namoro católico: o que é e como viver bem','Namoro como tempo de discernimento para o matrimônio, castidade, conhecer-se, oração juntos, Teologia do Corpo (São João Paulo II) mencionada com cuidado.')
add('D1',d,'castidade-no-namoro','Castidade no namoro: o que a Igreja ensina','CIC 2337-2350 (castidade), 2350 (noivos), relações sexuais reservadas ao matrimônio (CIC 2353, 2391), confissão e recomeço, tom acolhedor.')
add('D1',d,'como-discernir-a-vocacao','Como discernir a vocação: guia católico','Vocação universal à santidade (Lumen gentium 40; CIC 2013), matrimônio, sacerdócio, vida consagrada, oração, direção espiritual, sinais.')
add('D1',d,'o-que-e-a-vida-consagrada','O que é a vida consagrada na Igreja?','CIC 914-933, votos (link existente), formas: religiosos, monges, virgens consagradas, institutos seculares.')
add('D1',s,'noivado-catolico-como-viver','Noivado católico: como viver e se preparar','Tempo de preparação, curso de noivos (link existente preparação), documentos, castidade (CIC 2350), escolher a paróquia e a data.')
add('D1',d,'namoro-com-pessoa-de-outra-religiao','Namoro e casamento com quem é de outra religião','Casamentos mistos e disparidade de culto (CIC 1633-1637; CDC cân. 1086 e 1124-1125), licença/dispensa do bispo, compromissos da parte católica.')
add('D1',c,'virtude-da-fe','Virtude da fé: o que é e como crescer nela','CIC 1814-1816, 142-165, Hb 11,1, pecados contra a fé (CIC 2088-2089), como cultivar.')
add('D1',c,'virtude-da-esperanca','Virtude da esperança: o que é e como viver','CIC 1817-1821, Rm 5,5, desespero e presunção (CIC 2091-2092), Spe salvi (Bento XVI, 2007).')
add('D1',c,'virtude-da-caridade','Virtude da caridade: o maior mandamento','CIC 1822-1829, 1Cor 13, Mt 22,37-40, Deus caritas est (Bento XVI, 2005, link existente se houver na lista), obras de misericórdia (CIC 2447).')
# D2: cardeais + capitais
add('D2',c,'virtude-da-prudencia','Prudência: a virtude que guia as decisões','CIC 1806, "auriga virtutum" (cocheiro das virtudes) citado no Catecismo, São Tomás, partes da prudência, pecados opostos (imprudência, astúcia).')
add('D2',c,'virtude-da-justica','Justiça: a virtude de dar a cada um o que é seu','CIC 1807, justiça para com Deus (virtude da religião), justiça social (CIC 1928-1942), Lv 19,15.')
add('D2',c,'virtude-da-fortaleza','Fortaleza: a virtude da coragem cristã','CIC 1808, dom da fortaleza (CIC 1831), mártires, Jo 16,33, perseverança.')
add('D2',c,'virtude-da-temperanca','Temperança: a virtude do equilíbrio cristão','CIC 1809, Eclo 18,30 (Sirácida), Tt 2,12, sobriedade, castidade, mansidão.')
add('D2',c,'pecado-da-soberba','Soberba: o pecado capital e como vencê-lo','CIC 1866, 2094, humildade como remédio, Lc 18,9-14 fariseu e publicano, Pr 16,18.')
add('D2',c,'pecado-da-avareza','Avareza: o pecado capital e como vencê-lo','CIC 1866, 2536, 2544-2547, 1Tm 6,10, Lc 12,15-21, generosidade e esmola.')
add('D2',c,'pecado-da-luxuria','Luxúria: o pecado capital e como vencê-lo','CIC 2351, castidade (CIC 2337ss), pornografia (CIC 2354), misericórdia e confissão, tom pastoral e discreto.')
add('D2',c,'pecado-da-ira','Ira: o pecado capital e como vencê-lo','CIC 2302-2304, ira justa versus pecado, Ef 4,26, mansidão (Mt 11,29), perdão.')
add('D2',c,'pecado-da-gula','Gula: o pecado capital e como vencê-lo','CIC 1866, 2290 (temperança, abusos de comida, álcool), jejum, sobriedade; não confundir com transtornos alimentares, que exigem cuidado médico.')
add('D2',c,'pecado-da-inveja','Inveja: o pecado capital e como vencê-la','CIC 2538-2540, Sb 2,24, alegrar-se com o bem do outro, caridade.')
add('D2',c,'pecado-da-preguica-acedia','Preguiça (acídia): o pecado capital da alma','CIC 2094 e 2733 (acídia), diferença entre preguiça física e acídia espiritual, perseverança na oração.')
# E: Leão XIV + temperamentos
add('E',doc,'papa-leao-xiv-biografia','Papa Leão XIV: quem é Robert Francis Prevost','Usar SOMENTE os fatos do briefing.')
add('E',doc,'por-que-o-papa-escolheu-o-nome-leao-xiv','Por que o Papa escolheu o nome Leão XIV?','Usar SOMENTE os fatos do briefing: referência a Leão XIII e à Rerum novarum diante de nova revolução industrial e da inteligência artificial.')
add('E',doc,'dilexi-te-exortacao-leao-xiv-resumo','Dilexi te: resumo da exortação de Leão XIV','Usar SOMENTE os fatos do briefing.')
add('E',doc,'magnifica-humanitas-enciclica-resumo','Magnifica humanitas: resumo da encíclica sobre IA','Usar SOMENTE os fatos do briefing.')
add('E',doc,'in-unitate-fidei-carta-leao-xiv-niceia','In unitate fidei: Leão XIV e os 1700 anos de Niceia','Carta apostólica de 23 de novembro de 2025 no 1.700º aniversário do Concílio de Niceia (325). Fatos sobre Niceia: condenou o arianismo, afirmou que o Filho é consubstancial (homoousios) ao Pai, origem do Credo niceno; ligar com /oracoes-do-dia-a-dia/oracao-do-credo-niceno-constantinopolitano e /santos-e-oracoes/santo-atanasio-defensor-fe-nicena. Não inventar conteúdo da carta além disso: descrever a carta de forma genérica.')
add('E',d,'os-quatro-temperamentos-e-a-vida-espiritual','Os quatro temperamentos e a vida espiritual','Origem antiga (Hipócrates, Galeno), uso na tradição espiritual (Pe. Conrad Hock, livro "Os quatro temperamentos"; Art e Laraine Bennett, "O temperamento que Deus te deu"), deixar claro que não é doutrina da Igreja nem diagnóstico; graça supõe a natureza; link para /teste-de-temperamento.')
add('E',d,'temperamento-colerico','Temperamento colérico: virtudes, desafios e santidade','Traços, forças (liderança, determinação), desafios (ira, orgulho, impaciência), virtudes a cultivar (mansidão, humildade), conselhos de oração; link /teste-de-temperamento.')
add('E',d,'temperamento-sanguineo','Temperamento sanguíneo: virtudes, desafios e santidade','Traços (sociável, entusiasta), desafios (inconstância, superficialidade), virtudes (perseverança, recolhimento), conselhos.')
add('E',d,'temperamento-melancolico','Temperamento melancólico: virtudes, desafios e santidade','Traços (profundo, idealista, sensível), desafios (pessimismo, escrúpulo, rancor), virtudes (confiança, magnanimidade), deixar claro que não é depressão.')
add('E',d,'temperamento-fleumatico','Temperamento fleumático: virtudes, desafios e santidade','Traços (calmo, pacificador), desafios (indolência, omissão), virtudes (zelo, diligência), conselhos.')
json.dump(P, open('_plano.json','w'), ensure_ascii=False, indent=1)
print({k:len(v) for k,v in P.items()}, sum(len(v) for v in P.values()))
